const body = $json;
let warning = [];

// Normalize product input
if (!body.product || body.product.trim() === "") {
  body.product = "phone";
  warning.push("⚠️ Product missing, default used");
}

// Clean input
body.product = body.product.toLowerCase().trim();

// Fix budget
if (!body.budget || isNaN(body.budget)) {
  body.budget = 50000;
  warning.push("⚠️ Invalid budget, default used");
}

// Clean brand
if (body.brand) {
  body.brand = body.brand.toLowerCase().trim();
}

// General typo correction (multi-category)
const corrections = {
  "iphon": "iphone",
  "samsng": "samsung",
  "laptp": "laptop",
  "headphne": "headphones",
  "biryni": "biryani",
  "piza": "pizza",
  "shoos": "shoes"
};

if (corrections[body.product]) {
  body.product = corrections[body.product];
  warning.push(`🔄 Corrected product to ${body.product}`);
}

return [
  {
    json: {
      body,
      warning
    }
  }
];

